## 3. Result-Generation Logic (form data → recommendation)

The core result/recommendation logic is defined **inline** in the Compass page as the `evaluate()` function (there is no separate module logic lib). The generic PDF export helper used to render the result is included afterward.

Source: `client/src/pages/OocyteFreezeCompass.tsx`

```typescript
type OocyteFreezeIndication = "oncofertility" | "medical" | "elective" | "donor";

interface OocyteFreezeInputs {
  indication: OocyteFreezeIndication;
  femaleAge: number;
  gonadotoxicTherapy: boolean;
  therapyTimeline: string;
  prematureOvarianInsufficiency: boolean;
  geneticCondition: boolean;
  amhLevel: number;
  afcCount: number;
  partnerUnavailable: boolean;
  religiousObjection: boolean;
}

const defaultInputs: OocyteFreezeInputs = {
  indication: "oncofertility", femaleAge: 0, gonadotoxicTherapy: false,
  therapyTimeline: "", prematureOvarianInsufficiency: false, geneticCondition: false,
  amhLevel: 0, afcCount: 0, partnerUnavailable: false, religiousObjection: false,
};

function evaluate(inputs: OocyteFreezeInputs) {
  const warnings: string[] = [];
  const rationale: string[] = [];
  const references = [
    "Practice Committees of ASRM and SART. Mature oocyte cryopreservation: a guideline. Fertil Steril. 2013;99(1):37-43.",
    "Oktay K, et al. Fertility Preservation in Patients With Cancer: ASCO Clinical Practice Guideline Update. J Clin Oncol. 2018;36(19):1994-2001.",
    "ACOG Committee Opinion No. 584. Oocyte cryopreservation. Obstet Gynecol. 2014;123(1):221-222.",
    "Cobo A, et al. Oocyte vitrification as an efficient option for elective fertility preservation. Fertil Steril. 2016;105(3):755-764.",
  ];

  let recommendation = "not_indicated";
  let procedure = "";
  let cor = "I";
  let loe = "A";

  if (inputs.indication === "oncofertility" && inputs.gonadotoxicTherapy) {
    recommendation = "indicated";
    procedure = "Oocyte cryopreservation — oncofertility (medical indication)";
    cor = "I"; loe = "A";
    rationale.push("Gonadotoxic therapy planned: ASCO 2018 guideline recommends fertility preservation counseling and referral for all patients of reproductive age before gonadotoxic treatment.");
    rationale.push("Oocyte vitrification is no longer considered experimental (ASRM 2013) and is the standard of care for oncofertility.");
    if (inputs.therapyTimeline) {
      warnings.push(`Treatment timeline: ${inputs.therapyTimeline}. Coordinate with oncology — IVF stimulation typically requires 10–14 days.`);
    }
  } else if (inputs.indication === "medical" && (inputs.prematureOvarianInsufficiency || inputs.geneticCondition)) {
    recommendation = "indicated";
    procedure = "Oocyte cryopreservation — medical indication (POI/genetic condition)";
    cor = "I"; loe = "B";
    rationale.push("Medical indication for fertility preservation: premature ovarian insufficiency or genetic condition affecting future fertility.");
  } else if (inputs.indication === "elective") {
    recommendation = "consider";
    procedure = "Elective oocyte cryopreservation — patient counseling required";
    cor = "IIb"; loe = "C";
    rationale.push("Elective (social) egg freezing: ASRM does not endorse routine elective egg freezing for the sole purpose of circumventing reproductive aging.");
    warnings.push("Insurance coverage for elective egg freezing is rare. Most payers require a medical indication (oncofertility, POI, genetic condition).");
    if (inputs.femaleAge >= 38) {
      warnings.push(`Age ${inputs.femaleAge}: success rates decline significantly with age. Discuss realistic expectations — fewer usable eggs per cycle expected.`);
    }
  } else {
    recommendation = "not_indicated";
    procedure = "Oocyte cryopreservation — indication not established";
    rationale.push("No clear medical indication identified. Elective preservation may be appropriate but insurance coverage is unlikely.");
  }

  return { recommendation, procedure, cor, loe, warnings, rationale, references };
}
